"""Trade records."""


class Trade:
    def __init__(self, desk, volume):
        self.desk = desk
        self.volume = volume

    def __repr__(self):
        return "Trade(%r, %r)" % (self.desk, self.volume)


ROWS = [('fx', 15), ('metals', 21), ('fx', 44), ('bonds', 32), ('energy', 33)]


def load_trades():
    """Yield the stored trades one at a time."""
    for desk, volume in ROWS:
        yield Trade(desk, volume)


def feed_trades():
    """Endless feed of trades: repeats the stored rows for ever."""
    while True:
        for desk, volume in ROWS:
            yield Trade(desk, volume)
